//! Free-standing string formatting helpers.

/// Digits printed after the decimal point when no precision is requested.
pub const DEFAULT_PRECISION: usize = 1;

/// Namespace for the formatting helpers, mirroring the C++ `indicators::Format`
/// struct of static member functions.
pub struct Format;

impl Format {
    /// Formats a `0.0 ..= 1.0` ratio as a percentage with [`DEFAULT_PRECISION`]
    /// decimals: `0.25 -> "25.0%"`.
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, DEFAULT_PRECISION)
    }

    /// Formats a `0.0 ..= 1.0` ratio as a percentage with `precision` decimals:
    /// `(0.5, 2) -> "50.00%"`.
    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        // The C++ side widens the float to double before printing it, so the
        // widening happens here too rather than scaling in f32.
        format!("{:.*}%", precision, f64::from(value) * 100.0)
    }

    /// Formats a raw counter pair: `(25, 100) -> "25/100"`.
    pub fn progress(current: i32, total: i32) -> String {
        format!("{}/{}", current, total)
    }
}

/// Divides `current` by `total` as a ratio, treating a non-positive `total` as
/// "nothing to do" so the widgets never print `inf` or `NaN`.
pub(crate) fn ratio(current: i32, total: i32) -> f32 {
    if total > 0 {
        current as f32 / total as f32
    } else {
        0.0
    }
}

