//! Spinner-style progress indicator.

use std::fmt;

use crate::format::{ratio, Format};

/// Braille frames the spinner cycles through, one per call to
/// [`CyclicProgress::next`].
const FRAMES: [&str; 8] = ["⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"];

/// A spinner paired with a percentage: the frame cycles on every step while the
/// percentage tracks `current` against `total`.
pub struct CyclicProgress {
    total: i32,
    current: i32,
}

impl CyclicProgress {
    pub fn new(total: i32) -> Self {
        Self { total, current: 0 }
    }

    /// Advances one step: the counter grows and the spinner moves to the next
    /// frame, wrapping around the end of [`FRAMES`].
    pub fn next(&mut self) {
        self.current += 1;
    }

    pub fn current(&self) -> i32 {
        self.current
    }

    pub fn total(&self) -> i32 {
        self.total
    }

    /// The braille glyph for the current step.
    pub fn frame(&self) -> &'static str {
        FRAMES[self.current.rem_euclid(FRAMES.len() as i32) as usize]
    }
}

impl fmt::Display for CyclicProgress {
    /// Renders as `"⢿ 60.0%"` — the C++ `str()`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{} {}",
            self.frame(),
            Format::percentage(ratio(self.current, self.total))
        )
    }
}

