//! Counter-style progress indicator.

use std::fmt;

use crate::format::{ratio, Format};

/// Tracks `current` out of `total` and renders both the percentage and the raw
/// counter pair.
#[derive(Default)]
pub struct ProgressDisplay {
    total: i32,
    current: i32,
}

impl ProgressDisplay {
    pub fn new(total: i32) -> Self {
        Self { total, current: 0 }
    }

    /// Sets the counter to an absolute value.
    pub fn update(&mut self, current: i32) {
        self.current = current;
    }

    /// Moves the counter forward by `delta`.
    pub fn increment(&mut self, delta: i32) {
        self.current += delta;
    }

    pub fn current(&self) -> i32 {
        self.current
    }

    pub fn total(&self) -> i32 {
        self.total
    }
}

impl fmt::Display for ProgressDisplay {
    /// Renders as `"Progress: 50.0% (25/50)"` — the C++ `display()`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Progress: {} ({})",
            Format::percentage(ratio(self.current, self.total)),
            Format::progress(self.current, self.total)
        )
    }
}

